/* Hand-written (not gen-code.cl): what the COSX analytic GRADIENT needs for
 * one shell pair, from ONE g-array / Rys-root pass. 7 components, layout
 * (grid, i, j, comp):
 *   0      (i|1/r_g|j)
 *   1..3   (nabla_a i| j)      same sign/convention as int1e_grids_ip
 *   4..6   (i| nabla_a j)      = int1e_grids_ip of the swapped (j,i) pair
 * The separate int1e_grids + int1e_grids_ip(i,j) + int1e_grids_ip(j,i)
 * calls each redo the roots and the g arrays. The root count is set to
 * what the products actually need (total order li+lj+1); the default
 * (li+1+lj+1)/2+1 would add a root whenever li+lj is even, and the extra
 * g entry of total order li+lj+2 that this leaves inexact is never read. */
void CINTgout1e_int1e_grids_vipj(double *gout, double *g, FINT *idx, CINTEnvVars *envs, FINT gout_empty) {
/* Accumulates straight into gout (no zeroed scratch + copy-back): with the
 * 1-2 roots typical here that traffic cost as much as the products. */
FINT ngrids = envs->ngrids;
FINT bgrids = MIN(ngrids - envs->grids_offset, GRID_BLKSIZE);
FINT nrys_roots = envs->nrys_roots;
FINT nf = envs->nf;
FINT ix, iy, iz, n, i, ig;
double *g0 = g;
double *gI = g0 + envs->g_size * 3;
double *gJ = gI + envs->g_size * 3;
G1E_GRIDS_D_I(gI, g0, envs->i_l+0, envs->j_l);
G1E_GRIDS_D_J(gJ, g0, envs->i_l+0, envs->j_l);
for (n = 0; n < nf; n++) {
ix = idx[0+n*3];
iy = idx[1+n*3];
iz = idx[2+n*3];
double *restrict o0 = gout + bgrids*(n*7+0);
double *restrict o1 = o0 + bgrids;
double *restrict o2 = o1 + bgrids;
double *restrict o3 = o2 + bgrids;
double *restrict o4 = o3 + bgrids;
double *restrict o5 = o4 + bgrids;
double *restrict o6 = o5 + bgrids;
for (i = 0; i < nrys_roots; i++) {
const double *restrict x0 = g0+ix+i*GRID_BLKSIZE, *restrict y0 = g0+iy+i*GRID_BLKSIZE, *restrict z0 = g0+iz+i*GRID_BLKSIZE;
const double *restrict xi = gI+ix+i*GRID_BLKSIZE, *restrict yi = gI+iy+i*GRID_BLKSIZE, *restrict zi = gI+iz+i*GRID_BLKSIZE;
const double *restrict xj = gJ+ix+i*GRID_BLKSIZE, *restrict yj = gJ+iy+i*GRID_BLKSIZE, *restrict zj = gJ+iz+i*GRID_BLKSIZE;
if (i == 0 && gout_empty) {
#pragma GCC ivdep
for (ig = 0; ig < bgrids; ig++) {
double yz = y0[ig] * z0[ig];
double xz = x0[ig] * z0[ig];
double xy = x0[ig] * y0[ig];
o0[ig] = x0[ig] * yz;
o1[ig] = xi[ig] * yz;
o2[ig] = yi[ig] * xz;
o3[ig] = zi[ig] * xy;
o4[ig] = xj[ig] * yz;
o5[ig] = yj[ig] * xz;
o6[ig] = zj[ig] * xy;
}
} else {
#pragma GCC ivdep
for (ig = 0; ig < bgrids; ig++) {
double yz = y0[ig] * z0[ig];
double xz = x0[ig] * z0[ig];
double xy = x0[ig] * y0[ig];
o0[ig] += x0[ig] * yz;
o1[ig] += xi[ig] * yz;
o2[ig] += yi[ig] * xz;
o3[ig] += zi[ig] * xy;
o4[ig] += xj[ig] * yz;
o5[ig] += yj[ig] * xz;
o6[ig] += zj[ig] * xy;
}
}}}}
static void _vipj_init(CINTEnvVars *envs, FINT *shls, FINT *atm, FINT natm, FINT *bas, FINT nbas, double *env) {
FINT ng[] = {1, 1, 0, 0, 2, 1, 0, 7};
ng[SLOT_RYS_ROOTS] = (bas(ANG_OF, shls[0]) + bas(ANG_OF, shls[1]) + 1) / 2 + 1;
CINTinit_int1e_grids_EnvVars(envs, ng, shls, atm, natm, bas, nbas, env);
envs->f_gout = &CINTgout1e_int1e_grids_vipj;
}
