/* COSX analytic gradient: everything the pair loop needs from one shell
 * pair (i in shell si, j in shell sj) on one grid block, contracted in the
 * kernel instead of materialising the (g,i,j,7) integral block (value,
 * bra and ket first derivatives) and contracting it outside. With
 * A_ab(g) the ESP integral over Cartesian components and dA its
 * derivatives (same sign convention as int1e_grids_ip, i.e. -dA/dR):
 *   GA_i(g,a) = sum_b A_ab Fj_b      GT_j(g,b) = sum_a A_ab Pi_a
 *   GA_j(g,b) = sum_a A_ab Fi_a      GT_i(g,a) = sum_b A_ab Pj_b   (si != sj)
 *   T_bra(g,d) = sum_ab th_ab dA_ab/dRi,   T_ket(g,d) likewise for j,
 *   th_ab = Pi_a Fj_b + Pj_b Fi_a  (si != sj),  Pi_a Fj_b  (si == sj)
 * Inputs per spin, spherical (or Cartesian when sph == 0) and already
 * scaled by the AO normalisation:
 *   vi(nb, di, 2, nspin)  [F, P] for shell si;  vj(nb, dj, 2, nspin)
 * Outputs (overwritten), same basis as the inputs, each times sgw(g):
 *   oi(nb, di, 2, nspin)  [GA_i, GT_i];  oj(nb, dj, 2, nspin) [GA_j, GT_j]
 *   ot(nb, 3, 2, nspin)   [T_bra, T_ket]
 * Single-contraction shells only (returns -1 otherwise; the caller falls
 * back to the separate integrals). One Rys pass per primitive pair with
 * the li+lj+1 roots the derivatives need. cache: >= the size returned by
 * a call with out == NULL is not provided; the caller passes the same
 * INT_CACHE_SIZE buffer it uses for the other grids kernels. */
double *CINTc2s_coeff_table(FINT l);
FINT CINTg0_1e_grids_nm(double *g, double cutoff, CINTEnvVars *envs, double *cache, double *gridsT, FINT nmax_reduce);

static void _to_cart(double *cart, const double *v, FINT nb, FINT l, FINT sph)
{
        /* cart(nb, nfc) = v(nb, nd) * C^T  with C(nfc, nd) */
        FINT nfc = (l+1)*(l+2)/2, nd = sph ? 2*l+1 : nfc;
        FINT a, i, ig;
        if (!sph) { for (i = 0; i < nb*nfc; i++) cart[i] = v[i]; return; }
        double *c = CINTc2s_coeff_table(l);
        for (a = 0; a < nfc; a++) {
                double *ca = cart + nb*a;
                for (ig = 0; ig < nb; ig++) ca[ig] = 0;
                for (i = 0; i < nd; i++) {
                        double cc = c[a + nfc*i];
                        if (cc == 0) continue;
                        const double *vi = v + nb*i;
                        for (ig = 0; ig < nb; ig++) ca[ig] += cc * vi[ig];
                }
        }
}

static void _from_cart(double *v, const double *cart, const double *sgw, FINT nb, FINT l, FINT sph)
{
        FINT nfc = (l+1)*(l+2)/2, nd = sph ? 2*l+1 : nfc;
        FINT a, i, ig;
        double *c = sph ? CINTc2s_coeff_table(l) : NULL;
        for (i = 0; i < nd; i++) {
                double *vi = v + nb*i;
                if (!sph) {
                        for (ig = 0; ig < nb; ig++) vi[ig] = sgw[ig] * cart[ig + nb*i];
                        continue;
                }
                for (ig = 0; ig < nb; ig++) vi[ig] = 0;
                for (a = 0; a < nfc; a++) {
                        double cc = c[a + nfc*i];
                        if (cc == 0) continue;
                        const double *ca = cart + nb*a;
                        for (ig = 0; ig < nb; ig++) vi[ig] += cc * ca[ig];
                }
                for (ig = 0; ig < nb; ig++) vi[ig] *= sgw[ig];
        }
}

int cosx_grad_contract(FINT *shls, FINT *atm, FINT natm, FINT *bas, FINT nbas, double *env,
                       FINT sph, FINT nspin, const double *vi, const double *vj, const double *sgw,
                       double *oi, double *oj, double *ot, double *cache)
{
        FINT i_sh = shls[0], j_sh = shls[1];
        if (bas(NCTR_OF, i_sh) != 1 || bas(NCTR_OF, j_sh) != 1) return -1;
        FINT li = bas(ANG_OF, i_sh), lj = bas(ANG_OF, j_sh);
        FINT ng[] = {1, 1, 0, 0, 2, 1, 0, 1};
        ng[SLOT_RYS_ROOTS] = (li + lj + 1) / 2 + 1;
        CINTEnvVars envs;
        CINTinit_int1e_grids_EnvVars(&envs, ng, shls, atm, natm, bas, nbas, env);
        const FINT same = (i_sh == j_sh);
        const FINT nb = envs.ngrids;
        const FINT nfi = envs.nfi, nfj = envs.nfj;
        const FINT di = sph ? 2*li+1 : nfi, dj = sph ? 2*lj+1 : nfj;
        const FINT nroots = envs.nrys_roots;
        FINT i_prim = bas(NPRIM_OF, i_sh), j_prim = bas(NPRIM_OF, j_sh);
        double *ai = env + bas(PTR_EXP, i_sh), *aj = env + bas(PTR_EXP, j_sh);
        double *ci = env + bas(PTR_COEFF, i_sh), *cj = env + bas(PTR_COEFF, j_sh);
        FINT s, a, b, n, r, ig, d, ip, jp;

        /* Cartesian inputs/outputs for the whole block: [F,P] x nspin */
        double *ci_v = cache;                       /* nb*nfi*2*nspin */
        double *cj_v = ci_v + nb*nfi*2*nspin;       /* nb*nfj*2*nspin */
        double *co_i = cj_v + nb*nfj*2*nspin;       /* nb*nfi*2*nspin */
        double *co_j = co_i + nb*nfi*2*nspin;       /* nb*nfj*2*nspin */
        double *co_t = co_j + nb*nfj*2*nspin;       /* nb*6*nspin */
        double *work = co_t + nb*6*nspin;
        for (s = 0; s < 2*nspin; s++) {
                _to_cart(ci_v + nb*nfi*s, vi + nb*di*s, nb, li, sph);
                _to_cart(cj_v + nb*nfj*s, vj + nb*dj*s, nb, lj, sph);
        }
        FINT nzero = nb*(nfi+nfj)*4*nspin + nb*6*nspin;
        for (n = 0; n < nzero; n++) co_i[n] = 0;

        double *log_maxci = work;
        double *log_maxcj = log_maxci + i_prim;
        PairData *pdata_base = (PairData *)(((uintptr_t)(log_maxcj + j_prim) + 7) & (-(uintptr_t)8));
        double *p = (double *)(pdata_base + i_prim*j_prim);
        CINTOpt_log_max_pgto_coeff(log_maxci, ci, i_prim, 1);
        CINTOpt_log_max_pgto_coeff(log_maxcj, cj, j_prim, 1);
        if (CINTset_pairdata(pdata_base, ai, aj, envs.ri, envs.rj, log_maxci, log_maxcj,
                             envs.li_ceil, envs.lj_ceil, i_prim, j_prim,
                             SQUARE(envs.rirj), envs.expcutoff, env)) {
                goto finish;
        }
        FINT *idx = (FINT *)p;
        p += (nfi*nfj*3*sizeof(FINT) + 7) / 8 + 1;
        CINTg1e_index_xyz(idx, &envs);
        double *gridsT = (double *)(((uintptr_t)p + 63) & (-(uintptr_t)64));
        double *g0 = gridsT + GRID_BLKSIZE*3;
        double *gI = g0 + envs.g_size*3;
        double *gJ = gI + envs.g_size*3;
        /* primitive-summed Cartesian block: (GRID_BLKSIZE, 7, nf) */
        double *gc = gJ + envs.g_size*3;
        double *gcache = gc + 7*GRID_BLKSIZE*nfi*nfj;
        double *grids = envs.grids;
        FINT goff, bg, first;
        for (goff = 0; goff < nb; goff += GRID_BLKSIZE) {
                envs.grids_offset = goff;
                bg = MIN(nb - goff, GRID_BLKSIZE);
                for (ig = 0; ig < bg; ig++) {
                        gridsT[ig+GRID_BLKSIZE*0] = grids[(goff+ig)*3+0];
                        gridsT[ig+GRID_BLKSIZE*1] = grids[(goff+ig)*3+1];
                        gridsT[ig+GRID_BLKSIZE*2] = grids[(goff+ig)*3+2];
                }
                first = 1;
                PairData *pd = pdata_base;
                for (jp = 0; jp < j_prim; jp++) {
                envs.aj[0] = aj[jp];
                for (ip = 0; ip < i_prim; ip++, pd++) {
                        if (pd->cceij > envs.expcutoff) continue;
                        envs.ai[0] = ai[ip];
                        envs.rij[0] = pd->rij[0];
                        envs.rij[1] = pd->rij[1];
                        envs.rij[2] = pd->rij[2];
                        envs.fac[0] = envs.common_factor * cj[jp] * ci[ip] * pd->eij;
                        CINTg0_1e_grids_nm(g0, envs.expcutoff - pd->cceij, &envs, gcache, gridsT, 1);
                        CINTnabla1i_grids(gI, g0, li, lj, &envs);
                        CINTnabla1j_grids(gJ, g0, li, lj, &envs);
                        for (n = 0; n < nfi*nfj; n++) {
                                FINT ix = idx[0+n*3], iy = idx[1+n*3], iz = idx[2+n*3];
                                double *restrict A = gc + 7*GRID_BLKSIZE*n;
                                double *restrict bx = A+GRID_BLKSIZE, *restrict by = A+2*GRID_BLKSIZE,
                                       *restrict bz = A+3*GRID_BLKSIZE, *restrict kx = A+4*GRID_BLKSIZE,
                                       *restrict ky = A+5*GRID_BLKSIZE, *restrict kz = A+6*GRID_BLKSIZE;
                                for (r = 0; r < nroots; r++) {
                                        const double *x0 = g0+ix+r*GRID_BLKSIZE, *y0 = g0+iy+r*GRID_BLKSIZE, *z0 = g0+iz+r*GRID_BLKSIZE;
                                        const double *xi = gI+ix+r*GRID_BLKSIZE, *yi = gI+iy+r*GRID_BLKSIZE, *zi = gI+iz+r*GRID_BLKSIZE;
                                        const double *xj = gJ+ix+r*GRID_BLKSIZE, *yj = gJ+iy+r*GRID_BLKSIZE, *zj = gJ+iz+r*GRID_BLKSIZE;
                                        if (r == 0 && first) {
#pragma GCC ivdep
                                        for (ig = 0; ig < bg; ig++) {
                                                double yz = y0[ig]*z0[ig], xz = x0[ig]*z0[ig], xy = x0[ig]*y0[ig];
                                                A[ig] = x0[ig]*yz;
                                                bx[ig] = xi[ig]*yz; by[ig] = yi[ig]*xz; bz[ig] = zi[ig]*xy;
                                                kx[ig] = xj[ig]*yz; ky[ig] = yj[ig]*xz; kz[ig] = zj[ig]*xy;
                                        }
                                        } else {
#pragma GCC ivdep
                                        for (ig = 0; ig < bg; ig++) {
                                                double yz = y0[ig]*z0[ig], xz = x0[ig]*z0[ig], xy = x0[ig]*y0[ig];
                                                A[ig] += x0[ig]*yz;
                                                bx[ig] += xi[ig]*yz; by[ig] += yi[ig]*xz; bz[ig] += zi[ig]*xy;
                                                kx[ig] += xj[ig]*yz; ky[ig] += yj[ig]*xz; kz[ig] += zj[ig]*xy;
                                        }
                                        }
                                }
                        }
                        first = 0;
                } }
                if (first) continue;   /* every primitive pair screened out */
                for (b = 0; b < nfj; b++) {
                for (a = 0; a < nfi; a++) {
                        n = a + nfi*b;
                        const double *restrict A = gc + 7*GRID_BLKSIZE*n;
                        const double *restrict bx = A+GRID_BLKSIZE, *restrict by = A+2*GRID_BLKSIZE,
                                     *restrict bz = A+3*GRID_BLKSIZE, *restrict kx = A+4*GRID_BLKSIZE,
                                     *restrict ky = A+5*GRID_BLKSIZE, *restrict kz = A+6*GRID_BLKSIZE;
                        for (s = 0; s < nspin; s++) {
                                const double *restrict Fi = ci_v + nb*nfi*(2*s+0) + nb*a + goff;
                                const double *restrict Pi = ci_v + nb*nfi*(2*s+1) + nb*a + goff;
                                const double *restrict Fj = cj_v + nb*nfj*(2*s+0) + nb*b + goff;
                                const double *restrict Pj = cj_v + nb*nfj*(2*s+1) + nb*b + goff;
                                double *restrict GAi = co_i + nb*nfi*(2*s+0) + nb*a + goff;
                                double *restrict GTi = co_i + nb*nfi*(2*s+1) + nb*a + goff;
                                double *restrict GAj = co_j + nb*nfj*(2*s+0) + nb*b + goff;
                                double *restrict GTj = co_j + nb*nfj*(2*s+1) + nb*b + goff;
                                double *restrict T = co_t + nb*6*s + goff;
                                if (same) {
#pragma GCC ivdep
                                for (ig = 0; ig < bg; ig++) {
                                        double th = Pi[ig]*Fj[ig];
                                        GAi[ig] += A[ig]*Fj[ig];
                                        GTj[ig] += A[ig]*Pi[ig];
                                        T[ig]      += th*bx[ig];
                                        T[ig+nb]   += th*by[ig];
                                        T[ig+2*nb] += th*bz[ig];
                                        T[ig+3*nb] += th*kx[ig];
                                        T[ig+4*nb] += th*ky[ig];
                                        T[ig+5*nb] += th*kz[ig];
                                }
                                } else {
#pragma GCC ivdep
                                for (ig = 0; ig < bg; ig++) {
                                        double th = Pi[ig]*Fj[ig] + Pj[ig]*Fi[ig];
                                        GAi[ig] += A[ig]*Fj[ig];
                                        GTj[ig] += A[ig]*Pi[ig];
                                        GAj[ig] += A[ig]*Fi[ig];
                                        GTi[ig] += A[ig]*Pj[ig];
                                        T[ig]      += th*bx[ig];
                                        T[ig+nb]   += th*by[ig];
                                        T[ig+2*nb] += th*bz[ig];
                                        T[ig+3*nb] += th*kx[ig];
                                        T[ig+4*nb] += th*ky[ig];
                                        T[ig+5*nb] += th*kz[ig];
                                }
                                }
                        }
                } }
        }
finish:
        for (s = 0; s < 2*nspin; s++) {
                _from_cart(oi + nb*di*s, co_i + nb*nfi*s, sgw, nb, li, sph);
                _from_cart(oj + nb*dj*s, co_j + nb*nfj*s, sgw, nb, lj, sph);
        }
        for (s = 0; s < nspin; s++) {
                for (d = 0; d < 6; d++) {
                        double *o = ot + nb*(6*s+d);
                        const double *c = co_t + nb*(6*s+d);
                        for (ig = 0; ig < nb; ig++) o[ig] = sgw[ig]*c[ig];
                }
        }
        return 0;
}

/* COSX K build (SCF): the value-only analogue of cosx_grad_contract. For a
 * shell pair (si, sj) on one grid block and nvec vectors per spin (F, and
 * the fitted Ph when the variational leg is on):
 *   oi(g,a) = sgw(g) sum_b A_ab(g) vj_b(g)
 *   oj(g,b) = sgw(g) sum_a A_ab(g) vi_a(g)      (si != sj; zero otherwise)
 * vi(nb, di, nvec, nspin), vj(nb, dj, nvec, nspin) in the caller's basis,
 * already scaled by the AO normalisation; oi/oj same layout, overwritten.
 * Returns -1 for a generally contracted shell. */
int cosx_val_contract(FINT *shls, FINT *atm, FINT natm, FINT *bas, FINT nbas, double *env,
                      FINT sph, FINT nvec, const double *vi, const double *vj, const double *sgw,
                      double *oi, double *oj, double *cache)
{
        FINT i_sh = shls[0], j_sh = shls[1];
        if (bas(NCTR_OF, i_sh) != 1 || bas(NCTR_OF, j_sh) != 1) return -1;
        FINT li = bas(ANG_OF, i_sh), lj = bas(ANG_OF, j_sh);
        FINT ng[] = {0, 0, 0, 0, 0, 1, 0, 1};
        CINTEnvVars envs;
        CINTinit_int1e_grids_EnvVars(&envs, ng, shls, atm, natm, bas, nbas, env);
        const FINT same = (i_sh == j_sh);
        const FINT nb = envs.ngrids;
        const FINT nfi = envs.nfi, nfj = envs.nfj;
        const FINT di = sph ? 2*li+1 : nfi, dj = sph ? 2*lj+1 : nfj;
        const FINT nroots = envs.nrys_roots;
        FINT i_prim = bas(NPRIM_OF, i_sh), j_prim = bas(NPRIM_OF, j_sh);
        double *ai = env + bas(PTR_EXP, i_sh), *aj = env + bas(PTR_EXP, j_sh);
        double *ci = env + bas(PTR_COEFF, i_sh), *cj = env + bas(PTR_COEFF, j_sh);
        FINT s, a, b, n, r, ig, ip, jp;

        double *ci_v = cache;                    /* nb*nfi*nvec */
        double *cj_v = ci_v + nb*nfi*nvec;       /* nb*nfj*nvec */
        double *co_i = cj_v + nb*nfj*nvec;
        double *co_j = co_i + nb*nfi*nvec;
        double *work = co_j + nb*nfj*nvec;
        for (s = 0; s < nvec; s++) {
                _to_cart(ci_v + nb*nfi*s, vi + nb*di*s, nb, li, sph);
                _to_cart(cj_v + nb*nfj*s, vj + nb*dj*s, nb, lj, sph);
        }
        for (n = 0; n < nb*(nfi+nfj)*nvec; n++) co_i[n] = 0;

        double *log_maxci = work;
        double *log_maxcj = log_maxci + i_prim;
        PairData *pdata_base = (PairData *)(((uintptr_t)(log_maxcj + j_prim) + 7) & (-(uintptr_t)8));
        double *p = (double *)(pdata_base + i_prim*j_prim);
        CINTOpt_log_max_pgto_coeff(log_maxci, ci, i_prim, 1);
        CINTOpt_log_max_pgto_coeff(log_maxcj, cj, j_prim, 1);
        if (CINTset_pairdata(pdata_base, ai, aj, envs.ri, envs.rj, log_maxci, log_maxcj,
                             envs.li_ceil, envs.lj_ceil, i_prim, j_prim,
                             SQUARE(envs.rirj), envs.expcutoff, env)) {
                goto finish;
        }
        FINT *idx = (FINT *)p;
        p += (nfi*nfj*3*sizeof(FINT) + 7) / 8 + 1;
        CINTg1e_index_xyz(idx, &envs);
        double *gridsT = (double *)(((uintptr_t)p + 63) & (-(uintptr_t)64));
        double *g0 = gridsT + GRID_BLKSIZE*3;
        double *gc = g0 + envs.g_size*3;         /* (GRID_BLKSIZE, nf) */
        double *gcache = gc + GRID_BLKSIZE*nfi*nfj;
        double *grids = envs.grids;
        FINT goff, bg, first;
        for (goff = 0; goff < nb; goff += GRID_BLKSIZE) {
                envs.grids_offset = goff;
                bg = MIN(nb - goff, GRID_BLKSIZE);
                for (ig = 0; ig < bg; ig++) {
                        gridsT[ig+GRID_BLKSIZE*0] = grids[(goff+ig)*3+0];
                        gridsT[ig+GRID_BLKSIZE*1] = grids[(goff+ig)*3+1];
                        gridsT[ig+GRID_BLKSIZE*2] = grids[(goff+ig)*3+2];
                }
                first = 1;
                PairData *pd = pdata_base;
                for (jp = 0; jp < j_prim; jp++) {
                envs.aj[0] = aj[jp];
                for (ip = 0; ip < i_prim; ip++, pd++) {
                        if (pd->cceij > envs.expcutoff) continue;
                        envs.ai[0] = ai[ip];
                        envs.rij[0] = pd->rij[0];
                        envs.rij[1] = pd->rij[1];
                        envs.rij[2] = pd->rij[2];
                        envs.fac[0] = envs.common_factor * cj[jp] * ci[ip] * pd->eij;
                        CINTg0_1e_grids(g0, envs.expcutoff - pd->cceij, &envs, gcache, gridsT);
                        for (n = 0; n < nfi*nfj; n++) {
                                const double *gx = g0 + idx[0+n*3];
                                const double *gy = g0 + idx[1+n*3];
                                const double *gz = g0 + idx[2+n*3];
                                double *restrict A = gc + GRID_BLKSIZE*n;
                                for (r = 0; r < nroots; r++) {
                                        const double *x = gx + r*GRID_BLKSIZE, *y = gy + r*GRID_BLKSIZE, *z = gz + r*GRID_BLKSIZE;
                                        if (r == 0 && first) {
#pragma GCC ivdep
                                        for (ig = 0; ig < bg; ig++) A[ig] = x[ig]*y[ig]*z[ig];
                                        } else {
#pragma GCC ivdep
                                        for (ig = 0; ig < bg; ig++) A[ig] += x[ig]*y[ig]*z[ig];
                                        }
                                }
                        }
                        first = 0;
                } }
                if (first) continue;
                for (b = 0; b < nfj; b++) {
                for (a = 0; a < nfi; a++) {
                        const double *restrict A = gc + GRID_BLKSIZE*(a + nfi*b);
                        for (s = 0; s < nvec; s++) {
                                const double *restrict Vi = ci_v + nb*nfi*s + nb*a + goff;
                                const double *restrict Vj = cj_v + nb*nfj*s + nb*b + goff;
                                double *restrict Oi = co_i + nb*nfi*s + nb*a + goff;
                                double *restrict Oj = co_j + nb*nfj*s + nb*b + goff;
                                if (same) {
#pragma GCC ivdep
                                for (ig = 0; ig < bg; ig++) Oi[ig] += A[ig]*Vj[ig];
                                } else {
#pragma GCC ivdep
                                for (ig = 0; ig < bg; ig++) {
                                        Oi[ig] += A[ig]*Vj[ig];
                                        Oj[ig] += A[ig]*Vi[ig];
                                }
                                }
                        }
                } }
        }
finish:
        for (s = 0; s < nvec; s++) {
                _from_cart(oi + nb*di*s, co_i + nb*nfi*s, sgw, nb, li, sph);
                _from_cart(oj + nb*dj*s, co_j + nb*nfj*s, sgw, nb, lj, sph);
        }
        return 0;
}
